    pub struct CvPermissionWithdrawnPayload {}

    /// The payload of event `cv-operation-run`: Operation run.
    ///
    /// The assistant runs an operation for the person.
    #[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize, Deserialize)]
    pub struct CvOperationRunPayload {}

