                            next.completions = next
                                .completions
                                .checked_add(1u64)
                                .filter(|__v| *__v <= 9007199254740991u64)
                                .ok_or(overflow("sc-complete-i"))?;
                            next.created = next
                                .created
                                .checked_add(1u64)
